"""Requirement profiles: which business terms a target format requires.

* ``peppol-bis3`` is generated from the official Peppol syntax binding (cardinality min >= 1).
* other profiles are JSON files in data/profiles (generated by tools/import_profiles.py)
  and may ``extend`` another profile; a child can only make a requirement stricter.
"""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from functools import lru_cache

from ..resources import data_path
from ..semantic.catalog import catalog

LEVELS = {"optional": 0, "conditional": 1, "required": 2}


@dataclass
class Requirement:
    bt: str
    level: str
    sources: list[str] = field(default_factory=list)  # profile names that impose this level
    notes: list[str] = field(default_factory=list)
    name_sk: str | None = None
    when: list[str] = field(default_factory=list)  # e.g. ["CreditNote"]: conditional becomes required
    unless: list[str] = field(default_factory=list)  # BTs whose presence satisfies the requirement
    values: list[str] = field(default_factory=list)  # allowed values (e.g. Lidl: buyer VAT id, warehouse GLNs)
    values_note: str | None = None


@dataclass
class Profile:
    id: str
    name: str
    description: str
    extends: list[str]
    requirements: dict[str, Requirement]
    rules: str = "peppol"  # KoSIT configuration with the official rules of this standard
    # Additional Item Property vocabulary (BT-160 name -> {type: char|num|date, name_sk, note}), e.g. GS1 SK FMCG
    item_properties: dict = field(default_factory=dict)


def _peppol() -> dict:
    cat = catalog()
    req = {}
    for tid in cat.order:
        t = cat.get(tid)
        if t.min >= 1:
            req[tid] = {"level": "required"}
    # PEPPOL-EN16931-R003: buyer reference or purchase order reference must be present
    req.setdefault("BT-10", {"level": "conditional", "unless": ["BT-13"],
                             "note": "PEPPOL-EN16931-R003: povinná je BT-10 Buyer reference nebo BT-13 číslo objednávky."})
    req.setdefault("BT-9", {"level": "conditional", "unless": ["BT-20"],
                            "note": "BR-CO-25: při kladné částce k úhradě musí být uvedeno datum splatnosti (BT-9) nebo platební podmínky (BT-20)."})
    req.setdefault("BT-7", {"level": "conditional", "unless": ["BT-8"],
                            "note": "BR-CO-03: datum zdanitelného plnění (BT-7) nebo kód (BT-8), ne obojí."})
    return {"id": "peppol-bis3", "name": "Peppol BIS Billing 3.0",
            "description": "Povinné prvky dle kardinality OpenPEPPOL BIS 3.0 (UBL syntax binding).",
            "extends": [], "requirements": req}


@lru_cache(maxsize=None)
def _raw(pid: str) -> dict:
    if pid == "peppol-bis3":
        return _peppol()
    return json.loads(data_path("profiles", f"{pid}.json").read_text(encoding="utf-8"))


def _depth(pid: str) -> int:
    ext = _raw(pid).get("extends", [])
    return 1 + max((_depth(e) for e in ext), default=-1)


def available() -> list[dict]:
    """Standards first (Peppol, national CIUS), then retailer profiles (FMCG – Billa …) that extend them."""
    ids = ["peppol-bis3"] + [p.stem for p in data_path("profiles").glob("*.json")]
    # extended formats: the shared guideline (GS1 SK FMCG) first, then the retailers alphabetically
    ids.sort(key=lambda i: (_depth(i) >= 2 or bool(_raw(i).get("group")),
                            "item_properties" not in _raw(i), _depth(i) if _depth(i) < 2 else 0,
                            _raw(i)["name"].lower()))
    return [{"id": i, "name": _raw(i)["name"], "description": _raw(i).get("description", ""),
             "group": _raw(i).get("group") or ("Slovenská transpozice – rozšířené formáty" if _depth(i) >= 2 else "Standardy")}
            for i in ids]


@lru_cache(maxsize=None)
def load(pid: str) -> Profile:
    raw = _raw(pid)
    merged: dict[str, Requirement] = {}
    for parent in raw.get("extends", []):
        for bt, r in load(parent).requirements.items():
            merged[bt] = Requirement(bt, r.level, list(r.sources), list(r.notes), r.name_sk,
                                     list(r.when), list(r.unless), list(r.values), r.values_note)
    for bt, r in raw["requirements"].items():
        cur = merged.get(bt)
        lvl = r["level"]
        if cur is None:
            cur = merged[bt] = Requirement(bt, "optional")
        if r.get("name_sk"):
            cur.name_sk = r["name_sk"]
        if LEVELS[lvl] > LEVELS[cur.level]:
            cur.level = lvl
            cur.sources = [raw["name"]]
        elif LEVELS[lvl] == LEVELS[cur.level] and lvl != "optional" and raw["name"] not in cur.sources:
            cur.sources.append(raw["name"])
        for w in r.get("when", []):
            if w not in cur.when:
                cur.when.append(w)
        if "unless" in r and not r["unless"]:
            cur.unless = []  # stricter child: the parent's alternative no longer satisfies the requirement
        for u in r.get("unless", []):
            if u not in cur.unless:
                cur.unless.append(u)
        if r.get("values"):
            cur.values = list(r["values"])
            cur.values_note = f"{raw['name']}: {r.get('values_note') or 'povolené hodnoty'}"
        if r.get("note") and lvl != "optional":
            cur.notes.append(f"{raw['name']}: {r['note']}")
    rules = raw.get("rules") or next((load(p).rules for p in raw.get("extends", [])), "peppol")
    props: dict = {}
    for parent in raw.get("extends", []):
        props.update(load(parent).item_properties)
    props.update(raw.get("item_properties", {}))
    return Profile(raw["id"], raw["name"], raw.get("description", ""), raw.get("extends", []), merged, rules, props)
